using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.SGR.Condominios;using GraphApi.Services.SGR.Condominios;namespace GraphApi.Controllers.SGR.Condominios{    /// <summary>    /// Gestión de Condominios: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("SGR/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre Condominios")]    public class CondominiosController : Controller    {        private readonly ICondominiosService _objService;        public CondominiosController(ICondominiosService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los Condominios, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="condominioID">CondominioID</param>        /// <param name="nombreCondominio">NombreCondominio</param>        /// <param name="direccionCondominio">DireccionCondominio</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de Condominios</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar Condominios",            Description = "Devuelve Condominios aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadCondominios>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadCondominios>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? condominioID,            [FromQuery] string? nombreCondominio,            [FromQuery] string? direccionCondominio,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetCondominiosDynamic(                condominioID,                 nombreCondominio,                 direccionCondominio,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo Condominio.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del Condominio a crear.</param>        /// <returns>El Condominio recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear Condominios",            Description = "Inserta un nuevo Condominio en la base de datos."        )]        [ProducesResponseType(typeof(clReadCondominios), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadCondominios>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateCondominios objInput)        {            var vCreated = await _objService.CreateCondominios(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de Condominio.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del Condominio.</param>        /// <returns>El Condominio actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar Condominios",            Description = "Actualiza uno o varios campos de Condominio existente."        )]        [ProducesResponseType(typeof(clReadCondominios), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadCondominios>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateCondominios objInput)        {            var vUpdated = await _objService.UpdateCondominios(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un Condominio por su ID.        /// </summary>        [HttpDelete("{nCondominiosID:int}")]        [SwaggerOperation(            Summary = "Eliminar Condominio",            Description = "Borra un Condominio si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nCondominiosID)        {            var success = await _objService.DeleteCondominios(nCondominiosID);            return success ? NoContent() : NotFound();        }    }}